from gurobipy import GRB

# Parameters
supply = [[20, 30], [40, 10]]
demand = [[30, 30], [30, 10]]
limit = [[35, 25], [25, 30]]
cost = [[[2, 3], [4, 1]], [[3, 2], [2, 4]]]

# Create model
model = gp.Model()

# Decision variables
origins = 2
destinations = 2
products = 2

x = {}
for i in range(origins):
    for j in range(destinations):
        for p in range(products):
            x[(i, j, p)] = model.addVar(vtype=GRB.CONTINUOUS, name=f"x_{i}_{j}_{p}")

# Objective function
objective = 0
for i in range(origins):
    for j in range(destinations):
        for p in range(products):
            objective += cost[i][j][p] * x[(i, j, p)]
model.setObjective(objective, GRB.MINIMIZE)

# Supply constraints
for i in range(origins):
    for p in range(products):
        expr = 0
        for j in range(destinations):
            expr += x[(i, j, p)]
        model.addConstr(expr == supply[i][p], f"Supply_{i}_{p}")

# Demand constraints
for j in range(destinations):
    for p in range(products):
        expr = 0
        for i in range(origins):
            expr += x[(i, j, p)]
        model.addConstr(expr == demand[j][p], f"Demand_{j}_{p}")

# Shipping limit constraints
for i in range(origins):
    for j in range(destinations):
        expr = 0
        for p in range(products):
            expr += x[(i, j, p)]
        model.addConstr(expr <= limit[i][j], f"Limit_{i}_{j}")

# Optimize
model.optimize()

# Check if optimal and print the objective
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
