# Parameters
Cities = ["A", "B"]
Links = [["A", "B"]]
Products = ["Product1"]
Supply = [[10], [0]]
Demand = [[0], [10]]
ShipmentCost = [[[1]]]
Capacity = [[[10]]]
JointCapacity = [[10]]

# Create a mapping from city names to indices
city_to_index = {city: idx for idx, city in enumerate(Cities)}

# Create a set of (i,j) pairs for Links
links_set = set()
for link in Links:
    i_city = link[0]
    j_city = link[1]
    i = city_to_index[i_city]
    j = city_to_index[j_city]
    links_set.add((i, j))

# Create the model
model = gp.Model()

# Create variables
variables = {}
for (i, j) in links_set:
    for p in range(len(Products)):
        var_name = f'X_{i}_{j}_{p}'
        variables[(i, j, p)] = model.addVar(vtype=GRB.INTEGER, name=var_name)

# Add supply balance constraints
for i in range(len(Cities)):
    for p in range(len(Products)):
        expr = 0
        for j in range(len(Cities)):
            if (i, j) in links_set:
                expr += variables[(i, j, p)]
        model.addConstr(expr == Supply[i][p], name=f'Supply_{i}_{p}')

# Add demand balance constraints
for j in range(len(Cities)):
    for p in range(len(Products)):
        expr = 0
        for i in range(len(Cities)):
            if (i, j) in links_set:
                expr += variables[(i, j, p)]
        model.addConstr(expr == Demand[j][p], name=f'Demand_{j}_{p}')

# Add product-specific capacity constraints
for (i, j) in links_set:
    for p in range(len(Products)):
        model.addConstr(variables[(i, j, p)] <= Capacity[i][j][p], name=f'Capacity_{i}_{j}_{p}')

# Add joint capacity constraints
for (i, j) in links_set:
    expr = 0
    for p in range(len(Products)):
        expr += variables[(i, j, p)]
    model.addConstr(expr <= JointCapacity[i][j], name=f'JointCapacity_{i}_{j}')

# Set objective
obj_expr = 0
for (i, j) in links_set:
    for p in range(len(Products)):
        obj_expr += ShipmentCost[i][j][p] * variables[(i, j, p)]
model.setObjective(obj_expr, GRB.MINIMIZE)

# Optimize
model.optimize()

# Output the final objective if optimal
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")
else:
    print("No optimal solution found.")
